/**
 * @module clean
 *
 * Removes previously-generated files from the emitter's output directories
 * before a fresh emit, so that renamed or deleted TypeSpec types do not leave
 * stale `.g.cs` files behind.
 *
 * The main exports are {@link cleanOutputDirectories}, called by the emitter
 * before any file is written when `clean-output-dirs` is enabled (the default),
 * and {@link writeCleanupManifest}, called once every file has been written.
 *
 * ## Guardrails
 *
 * Cleaning is deliberately conservative — it must never delete hand-written
 * code, build output, or another tool's generated files, even when an output
 * directory is a project root (`models-output-dir: "."`).
 *
 * - **Manifest first.** Every run records the files it wrote in
 *   {@link MANIFEST_FILE_NAME} under the emitter output directory. When the
 *   manifest exists, cleanup deletes exactly the files listed in it — nothing
 *   is scanned.
 * - **Signature scan as a fallback.** Without a manifest (the first run, or
 *   after upgrading from a version that wrote none), a file is removed only
 *   when its name ends with {@link ResolvedOptions.fileExtension} **and** one
 *   of its first {@link SIGNATURE_LINE_LIMIT} lines carries this emitter's
 *   signature. A generic `<auto-generated>` marker is not enough: the .NET SDK
 *   (`*.GlobalUsings.g.cs`), EF Core (`*.Designer.cs`) and other generators
 *   write it too. Extension-matching files without the signature are kept and
 *   reported via the `output-file-left-behind` warning.
 * - **Never leaves the output directory.** Every candidate is confined to a
 *   configured output directory; symbolic links and junctions are never
 *   followed or deleted, and `bin`, `obj`, `node_modules` and dot-folders
 *   (`.git`, `.vs`, …) are never scanned.
 */

import {
  NoTarget,
  Program,
  getDirectoryPath,
  getRelativePathFromDirectory,
  normalizePath,
  resolvePath,
} from "@typespec/compiler";
import { ResolvedOptions } from "./emitter.js";
import { reportDiagnostic } from "./lib.js";
import { getWrittenFiles } from "./output.js";

/**
 * Name of the manifest file, written to the emitter output directory, that
 * lists every file the previous run wrote (paths relative to that directory).
 * It holds JSON but deliberately has no `.json` extension: the .NET Web SDK
 * copies every `*.json` in a project to the build and publish output.
 */
export const MANIFEST_FILE_NAME = ".tsp-aspnetcore-api-manifest";

/** Schema version written to (and required in) the manifest. */
const MANIFEST_VERSION = 1;

/** Shape of the cleanup manifest file. */
interface CleanupManifest {
  /** Manifest schema version; see {@link MANIFEST_VERSION}. */
  version: number;
  /** Generated files, relative to the emitter output directory, `/`-separated. */
  files: string[];
}

/**
 * Signature written into the header of every file this emitter generates (the
 * default `file` template and every validator template). Matched
 * case-insensitively.
 */
const GENERATED_SIGNATURE =
  /auto-generated by @massivescale\/tsp-aspnetcore-api/i;

/** Header line written by the `file` template of 1.0.0-beta releases. */
const LEGACY_HEADER_LINE =
  "// This file is AUTO-GENERATED. Do not edit this file directly.";

/** Only the first lines of a file are searched for the signature. */
const SIGNATURE_LINE_LIMIT = 10;

/**
 * Folder names never scanned during the signature fallback: build output and
 * package caches. Dot-folders (`.git`, `.vs`, `.idea`, …) are skipped as well.
 */
const SKIPPED_DIRECTORIES = new Set(["bin", "obj", "node_modules"]);

/** Whether paths compare case-insensitively on this platform. */
const CASE_INSENSITIVE_PATHS =
  process.platform === "win32" || process.platform === "darwin";

/**
 * Removes generated files from every configured output directory prior to
 * emitting.
 *
 * When a cleanup manifest from the previous run exists, exactly the files it
 * lists are removed. Otherwise each output directory is scanned recursively for
 * files carrying this emitter's signature (see the module guardrails).
 *
 * Missing directories (e.g. on a first-ever emit) are skipped silently.
 *
 * @param program - The compiled TypeSpec program, whose host provides the file
 *   system used by `emitFile` (real or in-memory).
 * @param options - Resolved emitter options carrying the output directory paths
 *   and the generated file extension.
 */
export async function cleanOutputDirectories(
  program: Program,
  options: ResolvedOptions,
): Promise<void> {
  const roots = outputDirectories(options);
  const manifest = await readManifest(program, options);
  if (manifest) {
    await removeManifestFiles(program, options, roots, manifest);
    return;
  }
  for (const dir of roots) {
    await cleanDirectory(program, dir, dir, options);
  }
}

/**
 * Writes the cleanup manifest listing every file written during this run, so
 * the next run can remove exactly those files.
 *
 * @param program - The compiled TypeSpec program.
 * @param options - Resolved emitter options (emitter output directory).
 */
export async function writeCleanupManifest(
  program: Program,
  options: ResolvedOptions,
): Promise<void> {
  const manifest: CleanupManifest = {
    version: MANIFEST_VERSION,
    files: getWrittenFiles(program).map((file) =>
      getRelativePathFromDirectory(options.emitterOutputDir, file, false),
    ),
  };
  const path = manifestPath(options);
  await program.host.mkdirp(getDirectoryPath(path));
  await program.host.writeFile(
    path,
    JSON.stringify(manifest, undefined, 2) + "\n",
  );
}

/** Absolute path of the cleanup manifest. */
function manifestPath(options: ResolvedOptions): string {
  return resolvePath(options.emitterOutputDir, MANIFEST_FILE_NAME);
}

/** Returns the distinct configured output directories. */
function outputDirectories(options: ResolvedOptions): string[] {
  return [
    ...new Set([
      options.modelsOutputDir,
      options.interfacesOutputDir,
      options.controllersOutputDir,
      options.servicesOutputDir,
      options.helpersOutputDir,
      options.validatorsOutputDir,
    ]),
  ];
}

/**
 * Reads and validates the cleanup manifest.
 *
 * @returns The manifest, or `undefined` when it is absent or malformed (the
 *   caller then falls back to the signature scan).
 */
async function readManifest(
  program: Program,
  options: ResolvedOptions,
): Promise<CleanupManifest | undefined> {
  let text: string;
  try {
    text = (await program.host.readFile(manifestPath(options))).text;
  } catch {
    return undefined;
  }
  try {
    const parsed = JSON.parse(text) as Partial<CleanupManifest>;
    if (
      parsed.version !== MANIFEST_VERSION ||
      !Array.isArray(parsed.files) ||
      !parsed.files.every((file) => typeof file === "string")
    ) {
      return undefined;
    }
    return { version: parsed.version, files: parsed.files };
  } catch {
    return undefined;
  }
}

/**
 * Deletes the files listed in the manifest. An entry is only deleted when it
 * still lies inside a configured output directory, ends with the generated
 * file extension, and is a regular file reached without following a link —
 * so a hand-edited or stale manifest cannot delete anything else.
 */
async function removeManifestFiles(
  program: Program,
  options: ResolvedOptions,
  roots: string[],
  manifest: CleanupManifest,
): Promise<void> {
  for (const entry of manifest.files) {
    const full = resolvePath(options.emitterOutputDir, entry);
    if (!full.endsWith(options.fileExtension)) continue;
    const root = roots.find((dir) => isWithin(dir, full));
    if (!root) continue;
    if (!(await isRegularFileWithoutLinks(program, root, full))) continue;
    await program.host.rm(full, { recursive: false });
  }
}

/**
 * Recursively scans a single directory, deleting files that carry this
 * emitter's signature and warning about extension-matching files that do not.
 *
 * @param program - The compiled TypeSpec program (host + diagnostics).
 * @param root - The configured output directory the scan started from.
 * @param dir - Absolute directory path to scan.
 * @param options - Resolved emitter options.
 */
async function cleanDirectory(
  program: Program,
  root: string,
  dir: string,
  options: ResolvedOptions,
): Promise<void> {
  let entries: string[];
  try {
    entries = await program.host.readDir(dir);
  } catch {
    // Directory does not exist yet (first emit) — nothing to clean.
    return;
  }

  for (const entry of entries) {
    const full = resolvePath(dir, entry);

    let isDirectory: boolean;
    try {
      isDirectory = (await program.host.stat(full)).isDirectory();
    } catch {
      continue;
    }

    // Symbolic links and junctions may point anywhere (another project, the
    // whole drive); they are neither followed nor deleted.
    if (await isLink(program, full)) continue;

    if (isDirectory) {
      if (isSkippedDirectory(entry)) continue;
      await cleanDirectory(program, root, full, options);
      continue;
    }

    // Only files that look like emitter output are ever candidates for
    // removal. Anything else (e.g. hand-written `.cs`) is left untouched.
    if (!entry.endsWith(options.fileExtension)) {
      continue;
    }

    if (await hasGeneratedSignature(program, full)) {
      await program.host.rm(full, { recursive: false });
    } else {
      // Looks generated by extension, but the signature is absent — keep it
      // and tell the user rather than risk deleting someone else's code.
      reportDiagnostic(program, {
        code: "output-file-left-behind",
        target: NoTarget,
        format: { path: full },
      });
    }
  }
}

/** Returns `true` for build-output, package-cache and dot-folders. */
function isSkippedDirectory(name: string): boolean {
  return name.startsWith(".") || SKIPPED_DIRECTORIES.has(name.toLowerCase());
}

/**
 * Returns `true` when `path` is a symbolic link or junction: its resolved real
 * path differs from the real path of its parent joined with its own name.
 */
async function isLink(program: Program, path: string): Promise<boolean> {
  try {
    const real = normalizePath(await program.host.realpath(path));
    const parentReal = normalizePath(
      await program.host.realpath(getDirectoryPath(path)),
    );
    const expected = resolvePath(
      parentReal,
      path.slice(path.lastIndexOf("/") + 1),
    );
    return !samePath(real, expected);
  } catch {
    // Treat an unresolvable path (dangling link, permission error) as a link
    // so it is left alone.
    return true;
  }
}

/**
 * Returns `true` when `path` is a regular file inside `root` and neither it nor
 * any folder between `root` and it is a link.
 */
async function isRegularFileWithoutLinks(
  program: Program,
  root: string,
  path: string,
): Promise<boolean> {
  try {
    if (!(await program.host.stat(path)).isFile()) return false;
  } catch {
    return false;
  }
  for (
    let current = path;
    isWithin(root, current) && !samePath(current, root);
    current = getDirectoryPath(current)
  ) {
    if (await isLink(program, current)) return false;
  }
  return true;
}

/** Returns `true` when `path` is `dir` or lies beneath it. */
function isWithin(dir: string, path: string): boolean {
  const relative = getRelativePathFromDirectory(dir, path, false);
  return (
    !relative.startsWith("..") &&
    !relative.startsWith("/") &&
    !/^[A-Za-z]:/.test(relative)
  );
}

/** Compares two normalized absolute paths, honoring platform case rules. */
function samePath(a: string, b: string): boolean {
  return CASE_INSENSITIVE_PATHS ? a.toLowerCase() === b.toLowerCase() : a === b;
}

/**
 * Reports whether a file carries this emitter's signature (or the header
 * written by 1.0.0-beta releases) in its first {@link SIGNATURE_LINE_LIMIT}
 * lines. A read failure is treated as "not generated" so the file is kept.
 *
 * @param program - The compiled TypeSpec program (host).
 * @param path - Absolute path to the candidate file.
 */
async function hasGeneratedSignature(
  program: Program,
  path: string,
): Promise<boolean> {
  let text: string;
  try {
    text = (await program.host.readFile(path)).text;
  } catch {
    return false;
  }
  const head = text.split(/\r?\n/, SIGNATURE_LINE_LIMIT);
  if (head.some((line) => GENERATED_SIGNATURE.test(line))) return true;

  // 1.0.0-beta headers carry no emitter name; require both the exact header
  // line and a copyright line naming this very file.
  const fileName = path.slice(path.lastIndexOf("/") + 1);
  return (
    head.some((line) => line.trim() === LEGACY_HEADER_LINE) &&
    head.some((line) => line.trim() === `// <copyright file="${fileName}" />`)
  );
}
